<?php require 'inc.php';
if(post()){if(isset($_POST['restock'])){q('UPDATE stock_item SET quantity=quantity+? WHERE item_id=?',[(int)$_POST['q'],$_POST['i']]);flash('Stock updated.');}
 else{$it=q('SELECT * FROM stock_item WHERE item_id=?',[$_POST['i']])->fetch();$qt=(int)$_POST['q'];if($qt<1||$qt>$it['quantity'])flash('Not enough stock.');
  q('UPDATE stock_item SET quantity=quantity-? WHERE item_id=?',[$qt,$it['item_id']]);q('INSERT INTO stock_issue(member_id,item_id,quantity,on_credit,issue_date,amount) VALUES(?,?,?,?,CURDATE(),?)',[$_POST['m'],$it['item_id'],$qt,isset($_POST['cr'])?1:0,$qt*$it['unit_price']]);flash('Item issued.');}}
start('Feed and drug stock');$io='';foreach(q('SELECT * FROM stock_item') as $s)$io.='<option value="'.$s['item_id'].'">'.e($s['item_name']).'</option>';?>
<div class="card wrap"><table><tr><th>Item</th><th>In stock</th><th>Reorder level</th><th>Unit price</th><th>Status</th></tr><?php foreach(q('SELECT * FROM stock_item') as $s)echo '<tr><td>'.e($s['item_name']).'</td><td>'.$s['quantity'].'</td><td>'.$s['reorder_level'].'</td><td>'.n($s['unit_price']).'</td><td><span class="tag '.($s['quantity']<=$s['reorder_level']?'bad">Low stock':'ok">OK').'</span></td></tr>';?></table></div>
<div class="card"><h3>Issue item to farmer</h3><form class="row" method="post"><div><label>Farmer</label><select name="m"><?=members_options()?></select></div><div><label>Item</label><select name="i"><?=$io?></select></div><div><label>Qty</label><input name="q" type="number" value="1" min="1" style="width:70px"></div><label><input type="checkbox" name="cr" checked> On credit</label><button>Issue</button></form></div>
<div class="card"><h3>Restock</h3><form class="row" method="post"><input type="hidden" name="restock" value="1"><div><label>Item</label><select name="i"><?=$io?></select></div><div><label>Qty added</label><input name="q" type="number" min="1" required style="width:90px"></div><button class="alt">Add stock</button></form></div><?php done();
